"use strict";
const{test}=require("node:test"),S=require("./support.cjs"),{assert}=S;
test("receipt and original result survive later commits and exact restart replay",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),out=await f.store.transact(q);await f.store.transact(S.request(f,await S.read(f),{folderUi:{later:true}}));await f.store.close();await f.store.open({version:1});const replay=await f.store.transact(q);assert.equal(replay.status,"replayed");assert.deepEqual(replay.result,out.result);assert.equal((await S.disk(f)).revision,2);assert.equal((await f.store.reconcile(q)).status,"replayed");});
for(const change of [q=>q.reason="changed",q=>q.changes[0].value={other:true},q=>q.observation.revision++,q=>q.observation.ownerEpoch=S.crypto.randomUUID()])test("changed stable operation evidence conflicts: "+change.toString(),async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));await f.store.transact(q);change(q);assert.equal((await f.store.transact(q)).code,"OPERATION_CONFLICT");assert.equal((await S.disk(f)).revision,1);});
test("absent request from previous owner epoch remains unknown",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));await f.store.close();await f.store.open({version:1});assert.equal((await f.store.transact(q)).status,"unknown");assert.equal((await f.store.reconcile(q)).status,"unknown");assert.equal((await S.disk(f)).revision,0);});
test("rename succeeds then acknowledgement fails: uncertainty reconciles original receipt",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),rename=S.fs.rename;let once=true,injected=false;S.fs.rename=async(...args)=>{const r=await rename(...args);if(once&&S.path.basename(args[1])==="data.json"){once=false;injected=true;throw Error("ack lost");}return r;};let out;try{out=await f.store.transact(q);}finally{S.fs.rename=rename;}assert.equal(injected,true);assert.equal(out.status,"uncertain");assert.equal((await S.disk(f)).receipts.length,1);assert.equal((await f.store.reconcile(q)).status,"replayed");assert.equal((await f.store.transact(q)).status,"replayed");});
test("uncertainty without receipt never automatically reexecutes",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),open=S.fs.open;S.fs.open=async(...args)=>{if(String(args[0]).includes('.application.'))throw Error("write unavailable");return open(...args);};let out;try{out=await f.store.transact(q);}finally{S.fs.open=open;}assert.equal(out.status,"uncertain");assert.equal((await f.store.reconcile(q)).status,"unknown");assert.equal((await f.store.transact(q)).status,"uncertain");assert.equal((await S.disk(f)).revision,0);});
for(const kind of ["checksum","receipt","revision","version","capability","missing-checksum","corrupt-json","missing-data"])test("integrity/compatibility refusal: "+kind,async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));await f.store.transact(q);await f.store.close();const d=await S.disk(f);if(kind==="checksum")d.checksum="0".repeat(64);if(kind==="receipt")d.receipts[0].request.reason="tamper";if(kind==="revision")d.revision++;if(kind==="version")d.version=2;if(kind==="capability")d.capabilities.push("unknown-mandatory");if(kind==="missing-checksum")delete d.checksum;if(kind==="missing-data")await S.fs.unlink(f.file);else await S.fs.writeFile(f.file,kind==="corrupt-json"?"{partial":JSON.stringify(d));await assert.rejects(f.store.open({version:1}));});
test("external valid re-encoding is not silently adopted by an open owner",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));await S.fs.writeFile(f.file,JSON.stringify(await S.disk(f),null,2));assert.equal((await f.store.transact(q)).code,"EXTERNAL_CHANGE");});

for(const part of ['previous-receipt','selected-effect','original-result'])test('recomputed outer checksum cannot hide corrupt receipt relationship: '+part,async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));await f.store.transact(q);await f.store.close();const d=await S.disk(f),r=d.receipts[0];if(part==='previous-receipt')r.previousReceiptDigest='a'.repeat(64);if(part==='selected-effect')r.selected[0].after.digest='b'.repeat(64);if(part==='original-result')r.result.revision=22;const{digest,...rb}=r;r.digest=S.C.hash(rb);const{checksum,...body}=d;await S.fs.writeFile(f.file,S.C.canonical(S.C.seal(body)));await assert.rejects(f.store.open({version:1}),{code:'INTEGRITY'});});
